package com.mohymods.kingdomsmp.gametest;
import java.util.*;
import com.mohymods.kingdomsmp.building.*;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.profession.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.storage.LevelResource;
/** Native original host writes + actual permitted correct-tool work, no geological proof injection. */
final class NativeGeologyRuntime {
 static void run(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();var mine=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.MINER.buildingId())).findFirst().orElseThrow();var p=server.getPlayerList().getPlayer(mine.owner());h.assertTrue(p!=null,"Original actual Miner owner attends");server.getPlayerList().deop(p.getGameProfile());var store=CommerceService.store(server);var track=store.professions(p.getUUID()).track(Profession.MINER);var marker=server.getWorldPath(LevelResource.ROOT).resolve("native-geology-proof.nbt");
  if(track.completedQuestIds().contains(NativeGeology.QUEST)){h.assertTrue(track.xp()==2000&&track.completedQuestIds().size()==14&&NativeGeology.count(p)>=3&&ConstructionService.structureIntact(level,mine),"Second JVM retains14earned2000XP/distinct native host areas/original Mine-Doran");var proof=AtomicNbt.read(marker);var retained=BlockPos.of(proof.getLong("retained"));level.getChunkAt(retained);h.assertTrue(level.getChunkAt(retained).getData(NativeOreProvenance.HOSTS).at(retained.asLong())!=null,"Native original host attachment persists");CommerceService.verifyReceipt(p);server.tickRateManager().setTickRate(20);com.mojang.logging.LogUtils.getLogger().info("NATIVE_GEOLOGY_RESTART_PASSED: authentic distinct geological working areas/untouched native host attachment/14earned2000XP/original13proofs/Mine-Doran/native receipt persist");h.succeed();return;}
  h.assertTrue(track.xp()==1800&&track.completedQuestIds().size()==13&&NativeGeology.count(p)==0,"Original actual13proofs/1800XP with no retrospective geological history");var old=BlockPos.of(AtomicNbt.read(server.getWorldPath(LevelResource.ROOT).resolve("native-journey-ore-proof.nbt")).getLong("retained"));level.getChunkAt(old);h.assertTrue(!level.getChunkAt(old).hasData(NativeOreProvenance.HOSTS),"Old legitimate ore does not invent a native host attachment");NativeCopperRuntime.mine(h,p,old);h.assertTrue(NativeGeology.count(p)==0,"Actual old unknown-host ore remains usable without retrospective geological credit");
  var positions=new ArrayList<BlockPos>();for(int x=208;x<212;x+=2)for(int z=160;z<164;z+=2)positions.addAll(NativeCopperRuntime.generated(h,p,x,z));var choices=new HashMap<String,List<BlockPos>>();for(var at:positions){var host=level.getChunkAt(at).getData(NativeOreProvenance.HOSTS).at(at.asLong());var metric=NativeCopperRuntime.metric(p,at);if(host!=null&&NativeOreQuests.eligible(metric,ProfessionRank.JOURNEYMAN,4))choices.computeIfAbsent(host,k->new ArrayList<>()).add(at);}h.assertTrue(choices.size()>=3,"Real future native OreFeature writes preserve distinct original stone settings: "+choices.keySet());
  var chosen=new ArrayList<BlockPos>();var used=new HashSet<Long>();for(var row:choices.entrySet())for(var at:row.getValue()){long chunk=ChunkPos.asLong(at.getX()>>4,at.getZ()>>4);if(used.add(chunk)){chosen.add(at);break;}}h.assertTrue(chosen.size()>=3,"Real distinct native hosts occur at distinct working chunks");var retained=positions.stream().filter(at->!chosen.contains(at)&&level.getChunkAt(at).getData(NativeOreProvenance.HOSTS).at(at.asLong())!=null).findFirst().orElseThrow();
  var denied=chosen.get(0);var guard=ClaimRuntimeTests.vanillaPlayer(level,UUID.nameUUIDFromBytes("GeoClaimGuard".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"GeoGuard");ClaimRuntimeTests.ftbUnclaim(level,denied);ClaimRuntimeTests.ftbClaim(guard,denied);BlacksmithRepairRuntime.near(p,denied);h.assertTrue(NativeOreProvenance.capture(p,denied,true)==null,"Current FTB refusal cannot authenticate geology");ClaimRuntimeTests.ftbUnclaim(level,denied);ClaimRuntimeTests.ftbClaim(p,denied);
  for(var at:chosen.subList(0,3))NativeCopperRuntime.mine(h,p,at);h.assertTrue(NativeGeology.count(p)==3,"Three actual successful personally visited native host removals, no count injection");CreateCraftRuntime.counter(p,mine);var review=ProfessionService.review(p,"quest:"+NativeGeology.QUEST);ProfessionService.confirm(p,review.nonce());boolean replay=false;try{ProfessionService.review(p,"quest:"+NativeGeology.QUEST);}catch(IllegalStateException expected){replay=true;}h.assertTrue(replay&&store.professions(p.getUUID()).track(Profession.MINER).xp()==2000,"Actual geological review earns200XPonce without changing earlier proofs");CommerceService.verifyReceipt(p);var proof=new net.minecraft.nbt.CompoundTag();proof.putLong("retained",retained.asLong());AtomicNbt.write(marker,proof);com.mojang.logging.LogUtils.getLogger().info("NATIVE_GEOLOGY_NATIVE_PASSED: actual new asynchronous OreFeature original hosts/three distinct native settings+chunks/personally visited permitted native mining, old unknown hosts/currentclaim/replay refusals/14earned2000XP; existing per-metric rank+tier gates and ore attachment schema unchanged, private future terrain/tools only");h.succeed();
 }
}
